    """Extend colored cross centers along their rows and columns.

    Original non-background cells, including green markers, are preserved.
    A blank-centered 3-cross marks a vertical gap that remains unfilled.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = [
        (r, c, grid[r][c])
        for r in range(1, h - 1)
        for c in range(1, w - 1)
        if grid[r][c] not in (0, 3)
        and grid[r - 1][c] == grid[r + 1][c] == 3
        and grid[r][c - 1] == grid[r][c + 1] == 3
    ]

    # Project every colored center across its full row, then its full column.
    for r, c, color in centers:
        for x in range(w):
            if grid[r][x] == 0:
                out[r][x] = color
    for r, c, color in centers:
        for y in range(h):
            if grid[y][c] == 0:
                out[y][c] = color

    # Blank-centered crosses identify a gap in their column projection.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
